import 'dart:async';
import 'dart:math';
import 'package:flutter/material.dart';

void main() {
  runApp(const GTA7App());
}

class GTA7App extends StatelessWidget {
  const GTA7App({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'GTA VII: Real Life v2.0',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        brightness: Brightness.dark,
        useMaterial3: true,
        scaffoldBackgroundColor: const Color(0xFF0D0B14),
        colorScheme: const ColorScheme.dark(
          primary: Color(0xFFFF2E93),
          secondary: Color(0xFF00F0FF),
          surface: Color(0xFF171424),
        ),
      ),
      home: const GameHomePage(),
    );
  }
}

class District {
  final String name;
  final String description;
  final double security;
  final Rect area;
  final Color color;

  const District({
    required this.name,
    required this.description,
    required this.security,
    required this.area,
    required this.color,
  });
}

class MapEntity {
  double x;
  double y;
  double vx;
  double vy;
  final bool isPolice;

  MapEntity({
    required this.x,
    required this.y,
    required this.vx,
    required this.vy,
    required this.isPolice,
  });
}

class StockItem {
  final String symbol;
  final String name;
  double price;
  double lastChange;
  int owned;

  StockItem({
    required this.symbol,
    required this.name,
    required this.price,
    this.lastChange = 0,
    this.owned = 0,
  });
}

class ContactNpc {
  final String name;
  final String role;
  int affinity;

  ContactNpc({
    required this.name,
    required this.role,
    required this.affinity,
  });
}

class GameHomePage extends StatefulWidget {
  const GameHomePage({super.key});

  @override
  State<GameHomePage> createState() => _GameHomePageState();
}

class _GameHomePageState extends State<GameHomePage> {
  final Random _rng = Random();
  Timer? _tickTimer;

  int _selectedTab = 0;

  // Tiempo y clima
  int day = 1;
  int hour = 9;
  int minute = 0;
  String weather = 'Soleado';
  final List<String> _weathers = ['Soleado', 'Atardecer Neón', 'Lluvia Tropical', 'Tormenta'];

  // Estadísticas vitales
  double health = 100;
  double energy = 100;
  double hunger = 15; // 0 lleno, 100 hambriento
  double thirst = 15; // 0 hidratado, 100 sediento
  double stress = 10;
  double hygiene = 95;
  int morality = 0; // -100 a +100
  int wantedStars = 0; // 0 a 5
  int education = 0; // 0 a 4
  int strength = 10;
  int criminalRecord = 0;

  // Finanzas
  double cash = 450;
  double bank = 1500;
  double fuel = 100;

  // Posición en el mapa (0..1)
  double playerX = 0.5;
  double playerY = 0.5;
  double? targetX;
  double? targetY;
  String currentVehicle = 'A pie';

  // Inventario y propiedades
  final Set<String> ownedVehicles = {'A pie'};
  final Set<String> ownedProperties = {};
  final Set<String> ownedBusinesses = {};
  final Set<String> ownedGear = {};

  // Feed social estilo GTA 6
  final List<String> socialFeed = [
    '@LeonidaNews: Bienvenido a Nueva Leonida. El clima hoy promete calor y oportunidades.',
    '@ViceLife: Los precios de las propiedades en la costa siguen subiendo.',
    '@PoliciaMetropolitana: Refuerzan patrullajes en el Centro Financiero.'
  ];

  // Bolsa y Cripto
  late List<StockItem> stocks;

  // Contactos
  late List<ContactNpc> contacts;

  // Entidades del mapa
  final List<MapEntity> entities = [];

  final List<District> districts = const [
    District(
      name: 'Centro Financiero',
      description: 'Bancos, rascacielos y alta vigilancia policial.',
      security: 0.90,
      area: Rect.fromLTWH(0.05, 0.05, 0.42, 0.40),
      color: Color(0xFF283593),
    ),
    District(
      name: 'Vice Beach',
      description: 'Playa neón, hoteles de lujo, clubes y mansiones.',
      security: 0.65,
      area: Rect.fromLTWH(0.53, 0.05, 0.42, 0.40),
      color: Color(0xFFAD1457),
    ),
    District(
      name: 'Distrito Industrial',
      description: 'Puerto, talleres clandestinos y fábricas.',
      security: 0.30,
      area: Rect.fromLTWH(0.05, 0.52, 0.42, 0.43),
      color: Color(0xFF4E342E),
    ),
    District(
      name: 'Barrio Sur',
      description: 'Calles intensas, comercio informal y bandas.',
      security: 0.25,
      area: Rect.fromLTWH(0.53, 0.52, 0.42, 0.43),
      color: Color(0xFF4527A0),
    ),
  ];

  @override
  void initState() {
    super.initState();
    stocks = [
      StockItem(symbol: 'LND', name: 'Leonida Tech', price: 145.0),
      StockItem(symbol: 'VCE', name: 'Vice Resorts', price: 88.0),
      StockItem(symbol: 'CRX', name: 'CriptoX', price: 320.0),
      StockItem(symbol: 'OIL', name: 'PetroSur', price: 62.0),
    ];
    contacts = [
      ContactNpc(name: 'Lucía', role: 'Pareja / Socia', affinity: 65),
      ContactNpc(name: 'Marco', role: 'Mecánico', affinity: 40),
      ContactNpc(name: 'Dra. Vega', role: 'Abogada', affinity: 30),
      ContactNpc(name: 'Kairo', role: 'Hacker', affinity: 25),
    ];
    for (int i = 0; i < 14; i++) {
      entities.add(MapEntity(
        x: 0.1 + _rng.nextDouble() * 0.8,
        y: 0.1 + _rng.nextDouble() * 0.8,
        vx: (_rng.nextDouble() - 0.5) * 0.012,
        vy: (_rng.nextDouble() - 0.5) * 0.012,
        isPolice: i < 4,
      ));
    }
    _tickTimer = Timer.periodic(const Duration(milliseconds: 120), (_) => _onTick());
  }

  @override
  void dispose() {
    _tickTimer?.cancel();
    super.dispose();
  }

  District get currentDistrict {
    for (final d in districts) {
      if (d.area.contains(Offset(playerX, playerY))) {
        return d;
      }
    }
    return districts[1];
  }

  double get _moveSpeed {
    switch (currentVehicle) {
      case 'Deportivo Neón':
        return 0.032;
      case 'Sedán Urbano':
        return 0.022;
      case 'Moto Deportiva':
        return 0.027;
      default:
        return 0.012;
    }
  }

  void _onTick() {
    if (!mounted || health <= 0) return;
    setState(() {
      if (targetX != null && targetY != null) {
        final dx = targetX! - playerX;
        final dy = targetY! - playerY;
        final dist = sqrt(dx * dx + dy * dy);
        if (dist < 0.015) {
          targetX = null;
          targetY = null;
        } else {
          final speed = (currentVehicle != 'A pie' && fuel <= 0) ? 0.008 : _moveSpeed;
          playerX = (playerX + (dx / dist) * speed).clamp(0.04, 0.96);
          playerY = (playerY + (dy / dist) * speed).clamp(0.04, 0.96);
          if (currentVehicle != 'A pie' && fuel > 0) {
            fuel = (fuel - 0.18).clamp(0, 100);
          } else {
            energy = (energy - 0.06).clamp(0, 100);
          }
        }
      }

      for (final e in entities) {
        if (e.isPolice && wantedStars > 0) {
          final dx = playerX - e.x;
          final dy = playerY - e.y;
          final dist = sqrt(dx * dx + dy * dy);
          if (dist > 0.001) {
            final chaseSpeed = 0.007 + wantedStars * 0.0022;
            e.x = (e.x + (dx / dist) * chaseSpeed).clamp(0.03, 0.97);
            e.y = (e.y + (dy / dist) * chaseSpeed).clamp(0.03, 0.97);
          }
          if (dist < 0.035 && _selectedTab == 0) {
            _triggerArrest('Una patrulla te interceptó en ${currentDistrict.name}.');
            break;
          }
        } else {
          e.x += e.vx;
          e.y += e.vy;
          if (e.x < 0.04 || e.x > 0.96) e.vx = -e.vx;
          if (e.y < 0.04 || e.y > 0.96) e.vy = -e.vy;
        }
      }

      minute += 1;
      if (minute >= 60) {
        minute = 0;
        _advanceHours(1, silent: true);
      }
    });
  }

  void _advanceHours(int hrs, {bool silent = false}) {
    hour += hrs;
    hunger = (hunger + hrs * 3.5).clamp(0, 100);
    thirst = (thirst + hrs * 4.5).clamp(0, 100);
    energy = (energy - hrs * 2.5).clamp(0, 100);
    hygiene = (hygiene - hrs * 1.8).clamp(0, 100);

    if (hunger >= 95 || thirst >= 95) {
      health = (health - hrs * 4).clamp(0, 100);
    }
    if (stress >= 90) {
      health = (health - hrs * 2).clamp(0, 100);
    }

    while (hour >= 24) {
      hour -= 24;
      day += 1;
      _onNewDay();
    }

    if (!silent && health <= 0) {
      _showAlert(
        'Hospital de Emergencia',
        'Tu salud llegó a 0. Te atendieron en urgencias por \$250 y recuperaste fuerzas.',
      );
      final bill = min(bank + cash, 250.0);
      if (bank >= bill) {
        bank -= bill;
      } else {
        cash = max(0, cash - bill);
      }
      health = 70;
      energy = 60;
      hunger = 30;
      thirst = 30;
    }
  }

  void _onNewDay() {
    weather = _weathers[_rng.nextInt(_weathers.length)];
    for (final s in stocks) {
      final pct = (_rng.nextDouble() - 0.48) * 0.22;
      s.lastChange = pct * 100;
      s.price = max(5.0, s.price * (1 + pct));
    }

    double passive = 0;
    if (ownedBusinesses.contains('Cafetería Urbana')) passive += 180;
    if (ownedBusinesses.contains('Taller Mecánico')) passive += 420;
    if (ownedBusinesses.contains('Club Nocturno Neón')) passive += 1100;
    if (passive > 0) {
      bank += passive;
      _postNews('@Finanzas: Tus negocios depositaron \$${passive.toStringAsFixed(0)} en tu cuenta.');
    }

    if (ownedProperties.isEmpty) {
      const rent = 65.0;
      if (bank >= rent) {
        bank -= rent;
      } else if (cash >= rent) {
        cash -= rent;
      } else {
        stress = (stress + 15).clamp(0, 100);
        _postNews('@Aviso: No pudiste pagar el alquiler diario. Tu estrés aumentó.');
      }
    }
  }

  void _postNews(String text) {
    socialFeed.insert(0, 'Día $day: $text');
    if (socialFeed.length > 25) {
      socialFeed.removeLast();
    }
  }

  void _notify(String msg) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).hideCurrentSnackBar();
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(msg),
        backgroundColor: const Color(0xFF231D38),
        duration: const Duration(seconds: 2),
      ),
    );
  }

  void _showAlert(String title, String body) {
    showDialog<void>(
      context: context,
      builder: (ctx) => AlertDialog(
        backgroundColor: const Color(0xFF1A162B),
        title: Text(title, style: const TextStyle(color: Color(0xFF00F0FF))),
        content: Text(body),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx),
            child: const Text('Entendido'),
          ),
        ],
      ),
    );
  }

  void _triggerArrest(String reason) {
    final fine = min(cash, 200.0 + wantedStars * 250.0);
    final hasLawyer = contacts.firstWhere((c) => c.name == 'Dra. Vega').affinity >= 60;
    final jailDays = hasLawyer ? max(1, wantedStars - 1) : wantedStars + 1;

    cash -= fine;
    wantedStars = 0;
    criminalRecord += 1;
    day += jailDays;
    energy = 80;
    stress = (stress + 20).clamp(0, 100);
    targetX = null;
    targetY = null;
    playerX = 0.5;
    playerY = 0.5;

    _postNews('@PoliciaMetropolitana: Detenido sospechoso tras operativo. Multa: \$${fine.toStringAsFixed(0)}.');
    final lawyerNote = hasLawyer ? '\n(Tu abogada redujo la condena)' : '';
    _showAlert(
      '¡ARRESTADO!',
      '$reason\n\nConfiscaron \$${fine.toStringAsFixed(0)} en efectivo y pasaste $jailDays día(s) en prisión.$lawyerNote',
    );
  }

  void _doLegalJob(String title, double pay, double energyCost, double stressGain, int reqEdu, int hrs) {
    if (education < reqEdu) {
      _notify('Necesitas Educación Nv.$reqEdu para este empleo.');
      return;
    }
    if (energy < energyCost) {
      _notify('Estás demasiado cansado. Duerme o toma café.');
      return;
    }
    setState(() {
      bank += pay;
      energy = (energy - energyCost).clamp(0, 100);
      stress = (stress + stressGain).clamp(0, 100);
      morality = (morality + 3).clamp(-100, 100);
      _advanceHours(hrs);
    });
    _notify('Trabajaste como $title y recibiste \$${pay.toStringAsFixed(0)} en tu banco.');
  }

  void _doCrime(String title, double minPay, double maxPay, double baseRisk, int starGain, int moralDrop) {
    if (energy < 20) {
      _notify('Necesitas al menos 20% de energía.');
      return;
    }
    final sec = currentDistrict.security;
    final gearBonus = ownedGear.contains('Kit de Hackeo') ? 0.10 : 0.0;
    final effectiveRisk = (baseRisk * (0.65 + sec * 0.7) - gearBonus).clamp(0.10, 0.92);

    setState(() {
      energy = (energy - 22).clamp(0, 100);
      morality = (morality - moralDrop).clamp(-100, 100);
      _advanceHours(3);
      if (_rng.nextDouble() > effectiveRisk) {
        final reward = minPay + _rng.nextDouble() * (maxPay - minPay);
        cash += reward;
        wantedStars = (wantedStars + starGain).clamp(0, 5);
        _postNews('@AlertaCiudad: Reportan $title en ${currentDistrict.name}. Buscan sospechoso.');
        _notify('¡Golpe exitoso! Ganaste \$${reward.toStringAsFixed(0)}. Búsqueda: $wantedStars★');
      } else {
        wantedStars = max(1, wantedStars + starGain).clamp(0, 5);
        _triggerArrest('Fallaste en: $title.');
      }
    });
  }

  void _buyItem(String name, double price, String category) {
    final total = cash + bank;
    if (total < price) {
      _notify('Fondos insuficientes (necesitas \$${price.toStringAsFixed(0)}).');
      return;
    }
    setState(() {
      if (bank >= price) {
        bank -= price;
      } else {
        final rem = price - bank;
        bank = 0;
        cash -= rem;
      }
      if (category == 'vehicle') {
        ownedVehicles.add(name);
        currentVehicle = name;
        fuel = 100;
        _postNews('@ViceMotors: Alguien acaba de estrenar un $name en la ciudad.');
      } else if (category == 'property') {
        ownedProperties.add(name);
        _postNews('@Inmobiliaria: Nueva adquisición de lujo: $name.');
      } else if (category == 'business') {
        ownedBusinesses.add(name);
        _postNews('@Economia: Nuevo dueño para $name.');
      } else if (category == 'gear') {
        ownedGear.add(name);
      } else if (category == 'fuel') {
        fuel = 100;
      } else if (category == 'medkit') {
        health = 100;
      }
    });
    _notify('Compraste: $name');
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        backgroundColor: const Color(0xFF141022),
        title: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                const Text(
                  'GTA VII: REAL LIFE',
                  style: TextStyle(
                    fontWeight: FontWeight.w900,
                    fontSize: 16,
                    letterSpacing: 1.1,
                    color: Color(0xFFFF2E93),
                  ),
                ),
                const SizedBox(width: 8),
                if (wantedStars > 0)
                  Text(
                    '★' * wantedStars,
                    style: const TextStyle(color: Colors.amber, fontSize: 15),
                  ),
              ],
            ),
            Text(
              'Día $day • ${hour.toString().padLeft(2, '0')}:${minute.toString().padLeft(2, '0')} • $weather • ${currentDistrict.name}',
              style: const TextStyle(fontSize: 11, color: Colors.white70),
            ),
          ],
        ),
        actions: [
          Padding(
            padding: const EdgeInsets.only(right: 12),
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              crossAxisAlignment: CrossAxisAlignment.end,
              children: [
                Text(
                  '💵 \$${cash.toStringAsFixed(0)}',
                  style: const TextStyle(color: Color(0xFF4ADE80), fontWeight: FontWeight.bold, fontSize: 13),
                ),
                Text(
                  '🏦 \$${bank.toStringAsFixed(0)}',
                  style: const TextStyle(color: Color(0xFF00F0FF), fontSize: 11),
                ),
              ],
            ),
          ),
        ],
      ),
      body: Column(
        children: [
          _buildVitalStrip(),
          Expanded(
            child: IndexedStack(
              index: _selectedTab,
              children: [
                _buildCityMapTab(),
                _buildLifeTab(),
                _buildActionsTab(),
                _buildPhoneTab(),
                _buildShopTab(),
              ],
            ),
          ),
        ],
      ),
      bottomNavigationBar: BottomNavigationBar(
        currentIndex: _selectedTab,
        onTap: (i) => setState(() => _selectedTab = i),
        type: BottomNavigationBarType.fixed,
        backgroundColor: const Color(0xFF141022),
        selectedItemColor: const Color(0xFFFF2E93),
        unselectedItemColor: Colors.white54,
        items: const [
          BottomNavigationBarItem(icon: Icon(Icons.map), label: 'Ciudad'),
          BottomNavigationBarItem(icon: Icon(Icons.favorite), label: 'Vida'),
          BottomNavigationBarItem(icon: Icon(Icons.work), label: 'Acciones'),
          BottomNavigationBarItem(icon: Icon(Icons.smartphone), label: 'Móvil'),
          BottomNavigationBarItem(icon: Icon(Icons.shopping_bag), label: 'Tienda'),
        ],
      ),
    );
  }

  Widget _buildVitalStrip() {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
      color: const Color(0xFF171326),
      child: Row(
        children: [
          _miniBar('Salud', health, Colors.redAccent),
          _miniBar('Energía', energy, Colors.amber),
          _miniBar('Hambre', 100 - hunger, Colors.orange),
          _miniBar('Sed', 100 - thirst, Colors.lightBlueAccent),
          _miniBar('Estrés', stress, Colors.purpleAccent),
        ],
      ),
    );
  }

  Widget _miniBar(String label, double val, Color color) {
    return Expanded(
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 3),
        child: Column(
          children: [
            Text(label, style: const TextStyle(fontSize: 9, color: Colors.white70)),
            const SizedBox(height: 2),
            LinearProgressIndicator(
              value: (val / 100).clamp(0.0, 1.0),
              minHeight: 5,
              backgroundColor: Colors.white12,
              valueColor: AlwaysStoppedAnimation<Color>(color),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildCityMapTab() {
    final isNight = hour < 6 || hour >= 20;
    final fuelText = currentVehicle != 'A pie' ? ' (Fuel ${fuel.toStringAsFixed(0)}%)' : '';
    return Column(
      children: [
        Padding(
          padding: const EdgeInsets.all(8.0),
          child: Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Text(
                'Vehículo: $currentVehicle$fuelText',
                style: const TextStyle(fontSize: 12, color: Color(0xFF00F0FF)),
              ),
              Text(
                'Seguridad: ${(currentDistrict.security * 100).toInt()}%',
                style: const TextStyle(fontSize: 12, color: Colors.white70),
              ),
            ],
          ),
        ),
        Expanded(
          child: Padding(
            padding: const EdgeInsets.symmetric(horizontal: 10),
            child: LayoutBuilder(
              builder: (context, constraints) {
                return GestureDetector(
                  onTapDown: (details) {
                    setState(() {
                      targetX = (details.localPosition.dx / constraints.maxWidth).clamp(0.04, 0.96);
                      targetY = (details.localPosition.dy / constraints.maxHeight).clamp(0.04, 0.96);
                    });
                  },
                  child: ClipRRect(
                    borderRadius: BorderRadius.circular(14),
                    child: CustomPaint(
                      size: Size(constraints.maxWidth, constraints.maxHeight),
                      painter: CityMapPainter(
                        districts: districts,
                        entities: entities,
                        playerX: playerX,
                        playerY: playerY,
                        targetX: targetX,
                        targetY: targetY,
                        isNight: isNight,
                        wantedStars: wantedStars,
                      ),
                    ),
                  ),
                );
              },
            ),
          ),
        ),
        Padding(
          padding: const EdgeInsets.all(10),
          child: Row(
            children: [
              Expanded(
                child: ElevatedButton.icon(
                  onPressed: () {
                    final list = ownedVehicles.toList();
                    final next = (list.indexOf(currentVehicle) + 1) % list.length;
                    setState(() => currentVehicle = list[next]);
                    _notify('Cambiaste a: $currentVehicle');
                  },
                  icon: const Icon(Icons.directions_car, size: 18),
                  label: const Text('Cambiar Vehículo'),
                ),
              ),
              const SizedBox(width: 8),
              if (wantedStars > 0)
                Expanded(
                  child: ElevatedButton.icon(
                    style: ElevatedButton.styleFrom(backgroundColor: Colors.redAccent),
                    onPressed: () {
                      final bribe = wantedStars * 300.0;
                      if (cash >= bribe) {
                        setState(() {
                          cash -= bribe;
                          wantedStars = 0;
                        });
                        _notify('Sobornaste y limpiaste tu búsqueda por \$${bribe.toStringAsFixed(0)}.');
                      } else {
                        _notify('Necesitas \$${bribe.toStringAsFixed(0)} en efectivo para escapar rápido.');
                      }
                    },
                    icon: const Icon(Icons.local_police, size: 18),
                    label: Text('Sobornar (\$${wantedStars * 300})'),
                  ),
                )
              else
                Expanded(
                  child: OutlinedButton.icon(
                    onPressed: () {
                      setState(() {
                        energy = 100;
                        stress = (stress - 22).clamp(0, 100);
                        _advanceHours(8);
                      });
                      _notify('Dormiste 8 horas. ¡Nuevo impulso!');
                    },
                    icon: const Icon(Icons.bedtime, size: 18),
                    label: const Text('Dormir 8h'),
                  ),
                ),
            ],
          ),
        ),
      ],
    );
  }

  Widget _buildLifeTab() {
    return ListView(
      padding: const EdgeInsets.all(12),
      children: [
        _sectionCard(
          'Estado Personal',
          'Moralidad: ${morality >= 0 ? "+$morality (Ciudadano)" : "$morality (Forajido)"}\n'
          'Educación: Nv.$education | Fuerza: $strength | Higiene: ${hygiene.toInt()}%\n'
          'Antecedentes penales: $criminalRecord | Propiedades: ${ownedProperties.length}',
        ),
        const SizedBox(height: 10),
        _actionTile('Cocinar en casa (\$12)', 'Reduce hambre y estrés (1h)', Icons.restaurant, () {
          if (cash + bank < 12) return _notify('Sin dinero suficiente.');
          setState(() {
            if (cash >= 12) {
              cash -= 12;
            } else {
              bank -= 12;
            }
            hunger = (hunger - 45).clamp(0, 100);
            thirst = (thirst - 30).clamp(0, 100);
            stress = (stress - 6).clamp(0, 100);
            _advanceHours(1);
          });
          _notify('Comiste sano en casa.');
        }),
        _actionTile('Restaurante de lujo en Vice Beach (\$55)', 'Llena hambre, sed y baja mucho estrés', Icons.local_dining, () {
          if (cash + bank < 55) return _notify('Sin dinero suficiente.');
          setState(() {
