class CityMapPainter extends CustomPainter {
  final List<District> districts;
  final List<MapEntity> entities;
  final double playerX;
  final double playerY;
  final double? targetX;
  final double? targetY;
  final bool isNight;
  final int wantedStars;

  CityMapPainter({
    required this.districts,
    required this.entities,
    required this.playerX,
    required this.playerY,
    required this.targetX,
    required this.targetY,
    required this.isNight,
    required this.wantedStars,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final bgPaint = Paint()..color = isNight ? const Color(0xFF0B0A12) : const Color(0xFF1E1B2E);
    canvas.drawRect(Offset.zero & size, bgPaint);

    for (final d in districts) {
      final rect = Rect.fromLTWH(
        d.area.left * size.width,
        d.area.top * size.height,
        d.area.width * size.width,
        d.area.height * size.height,
      );
      final paint = Paint()..color = d.color.withAlpha(isNight ? 95 : 140);
      canvas.drawRRect(RRect.fromRectAndRadius(rect, const Radius.circular(12)), paint);

      final tp = TextPainter(
        text: TextSpan(
          text: d.name,
          style: const TextStyle(color: Colors.white70, fontSize: 11, fontWeight: FontWeight.bold),
        ),
        textDirection: TextDirection.ltr,
      )..layout();
      tp.paint(canvas, Offset(rect.left + 8, rect.top + 8));
    }

    final roadPaint = Paint()
      ..color = Colors.white24
      ..strokeWidth = 3;
    canvas.drawLine(Offset(size.width * 0.5, 0), Offset(size.width * 0.5, size.height), roadPaint);
    canvas.drawLine(Offset(0, size.height * 0.485), Offset(size.width, size.height * 0.485), roadPaint);

    if (targetX != null && targetY != null) {
      final tPos = Offset(targetX! * size.width, targetY! * size.height);
      canvas.drawCircle(tPos, 8, Paint()..color = const Color(0xFF00F0FF).withAlpha(110));
    }

    for (final e in entities) {
      final pos = Offset(e.x * size.width, e.y * size.height);
      final p = Paint()
        ..color = e.isPolice
            ? (wantedStars > 0 ? Colors.redAccent : Colors.blueAccent)
            : Colors.white54;
      canvas.drawCircle(pos, e.isPolice ? 5.5 : 3.5, p);
    }

    final playerPos = Offset(playerX * size.width, playerY * size.height);
    canvas.drawCircle(playerPos, 11, Paint()..color = const Color(0xFFFF2E93).withAlpha(90));
    canvas.drawCircle(playerPos, 6, Paint()..color = const Color(0xFFFF2E93));
  }

  @override
  bool shouldRepaint(covariant CityMapPainter oldDelegate) => true;
}
